import type { CameraType, SpeedCamera } from '../types';
import { calculateDistanceMeters } from './radarData';

// Static tiles generated by scripts/fetch-cameras.mjs from OpenStreetMap data
const TILE_DEG = 2;
const BASE = `${import.meta.env.BASE_URL}cameras/`;

export const LOAD_RADIUS_M = 200_000;
// Reload once the driver has moved this far from where cameras were last loaded
export const RELOAD_DISTANCE_M = 50_000;

const CAMERA_NAMES: Record<CameraType, string> = {
  fixed: 'Speed camera',
  mobile: 'Mobile speed camera',
  red_light: 'Red light camera',
  average_speed: 'Average speed camera',
  tunnel: 'Tunnel camera',
  traffic: 'Traffic camera'
};

// [osmId, lat, lng, type, speedLimitKmh (0 = unknown), direction | null]
type TileRow = [number, number, number, CameraType, number, number | null];

// Live fallback when the static tiles haven't been generated yet
const OVERPASS_ENDPOINTS = [
  'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
  'https://overpass-api.de/api/interpreter'
];
const LIVE_CACHE_KEY = 'radarcam:live-cameras';
const LIVE_CACHE_MS = 24 * 60 * 60 * 1000;

let indexPromise: Promise<Set<string>> | null = null;
const tileCache = new Map<string, Promise<TileRow[]>>();

function loadIndex(): Promise<Set<string>> {
  indexPromise ??= fetch(`${BASE}index.json`)
    .then(r => {
      if (!r.ok) throw new Error(`Camera index unavailable (HTTP ${r.status})`);
      return r.json();
    })
    .then((idx: { tiles: string[] }) => new Set(idx.tiles))
    .catch(err => {
      indexPromise = null; // allow a retry on the next load
      throw err;
    });
  return indexPromise;
}

function loadTile(key: string): Promise<TileRow[]> {
  let p = tileCache.get(key);
  if (!p) {
    p = fetch(`${BASE}${key}.json`).then(r => (r.ok ? r.json() : []));
    p.catch(() => tileCache.delete(key));
    tileCache.set(key, p);
  }
  return p;
}

// Tile keys whose cells overlap a circle of `radiusM` around the point
function tilesAround(lat: number, lng: number, radiusM: number): string[] {
  const dLat = radiusM / 111_320;
  const cosLat = Math.max(Math.cos((lat * Math.PI) / 180), 0.01);
  const dLng = Math.min(dLat / cosLat, 180);
  const latMin = Math.floor(Math.max(lat - dLat, -90) / TILE_DEG);
  const latMax = Math.floor(Math.min(lat + dLat, 89.999) / TILE_DEG);
  const lngMin = Math.floor((lng - dLng) / TILE_DEG);
  const lngMax = Math.floor((lng + dLng) / TILE_DEG);
  const cols = 360 / TILE_DEG;
  const keys = new Set<string>();
  for (let y = latMin; y <= latMax; y++) {
    for (let x = lngMin; x <= lngMax; x++) {
      // Wrap across the antimeridian
      const wrapped = ((x + cols / 2) % cols + cols) % cols - cols / 2;
      keys.add(`${y}_${wrapped}`);
    }
  }
  return [...keys];
}

function parseMaxspeed(value?: string): number {
  const n = parseInt(value ?? '', 10);
  if (Number.isNaN(n)) return 0;
  return /mph/i.test(value ?? '') ? Math.round(n * 1.609344) : n;
}

function liveType(tags: Record<string, string>): CameraType {
  if (tags['camera:type'] === 'average') return 'average_speed';
  if (tags['camera:mount'] === 'mobile' || tags['camera:type'] === 'mobile') return 'mobile';
  return 'fixed';
}

// Queries Overpass directly for the cameras around a point (bounding box, filtered later)
async function loadLive(lat: number, lng: number): Promise<TileRow[]> {
  try {
    const cached = JSON.parse(localStorage.getItem(LIVE_CACHE_KEY) ?? 'null');
    if (cached && Date.now() - cached.at < LIVE_CACHE_MS &&
        calculateDistanceMeters(lat, lng, cached.lat, cached.lng) < RELOAD_DISTANCE_M) {
      return cached.rows;
    }
  } catch { /* storage unavailable */ }

  const dLat = LOAD_RADIUS_M / 111_320;
  const dLng = Math.min(dLat / Math.max(Math.cos((lat * Math.PI) / 180), 0.01), 180);
  const bbox = [lat - dLat, lng - dLng, lat + dLat, lng + dLng].map(n => n.toFixed(4)).join(',');
  const body = new URLSearchParams({ data: `[out:json][timeout:60];node["highway"="speed_camera"](${bbox});out body qt;` });

  let lastError: unknown;
  for (const url of OVERPASS_ENDPOINTS) {
    try {
      const res = await fetch(url, { method: 'POST', body, signal: AbortSignal.timeout(90_000) });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json: { elements: { id: number; lat: number; lon: number; tags?: Record<string, string> }[] } = await res.json();
      const rows: TileRow[] = json.elements.map(el => {
        const tags = el.tags ?? {};
        const direction = parseInt(tags.direction ?? '', 10);
        return [el.id, el.lat, el.lon, liveType(tags), parseMaxspeed(tags.maxspeed), Number.isNaN(direction) ? null : direction];
      });
      try {
        localStorage.setItem(LIVE_CACHE_KEY, JSON.stringify({ at: Date.now(), lat, lng, rows }));
      } catch { /* storage full or unavailable */ }
      return rows;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

async function loadRows(lat: number, lng: number): Promise<TileRow[][]> {
  let available: Set<string>;
  try {
    available = await loadIndex();
  } catch {
    return [await loadLive(lat, lng)];
  }
  const keys = tilesAround(lat, lng, LOAD_RADIUS_M).filter(k => available.has(k));
  return Promise.all(keys.map(loadTile));
}

// Loads every known camera within LOAD_RADIUS_M of the point
export async function loadCamerasAround(lat: number, lng: number): Promise<SpeedCamera[]> {
  const tiles = await loadRows(lat, lng);

  const cameras: SpeedCamera[] = [];
  for (const rows of tiles) {
    for (const [id, cLat, cLng, type, speedLimit, direction] of rows) {
      if (calculateDistanceMeters(lat, lng, cLat, cLng) > LOAD_RADIUS_M) continue;
      cameras.push({
        id: `osm_${id}`,
        lat: cLat,
        lng: cLng,
        type,
        speedLimit,
        direction: direction ?? undefined,
        name: CAMERA_NAMES[type],
        roadName: 'OpenStreetMap',
        verifiedCount: 0
      });
    }
  }
  return cameras;
}
